export declare const PROPERTIES: PropertyDef[];
export declare const AT_RULES: AtRuleDef[];
export declare const SELECTORS: SelectorDef[];
export declare const SHAPE_DOCS: ShapeDef[];
export declare const FUNCTIONS: FunctionDef[];
export {};
